<?php

namespace App\Repository;

use App\Entity\Category;
use App\Entity\Delegation;
use App\Entity\User;
use App\Enum\InitiativeEnum;
use Doctrine\ORM\AbstractQuery;
use Doctrine\ORM\EntityRepository;
use Doctrine\ORM\Query\Expr\Join;


/**
 * CategoryRepository
 *
 * This class was generated by the PhpStorm "Php Annotations" Plugin. Add your own custom
 * repository methods below.
 */
class CategoryRepository extends EntityRepository
{

    public function getCategoryOverview($type)
    {

        $type = InitiativeEnum::checkTypeName($type);

        if ($type !== false) {

            $qb = $this->createQueryBuilder('category')
                ->select('category.id, category.name, category.type, category.description, category.country, category.slug')
                ->addSelect('COUNT(initiative.id) count_initiative')
                ->addSelect('MAX(initiative.createdAt) last_initiative')
                ->innerJoin('category.initiatives', 'initiative', Join::WITH, 'category.id = initiative.category AND initiative.type = :type AND initiative.state = :state')
                ->setParameter('type', $type)
                ->addOrderBy('category.type')
                ->addOrderBy('count_initiative', 'DESC')
                ->groupBy('category.id');

            if ($type === InitiativeEnum::TYPE_PAST ||
                $type === InitiativeEnum::TYPE_PROGRAM
            ) {
                $qb->setParameter('state', InitiativeEnum::STATE_FINISHED);
            } else {
                $qb->setParameter('state', InitiativeEnum::STATE_ACTIVE);
            }

            return $qb
                ->getQuery()
                ->execute();

        }
    }
    public function getFutureInitiatives()
    {
        return $this->createQueryBuilder('category')
            ->select(['category', 'initiative'])
            ->leftJoin('category.initiatives', 'initiative')
            ->andWhere('initiative.type = 0')
            ->andWhere('initiative.state > 0')
            ->andWhere('initiative.state < 3')
            ->addOrderBy('category.type', 'asc')
            ->addOrderBy('initiative.createdAt', 'desc')
            ->getQuery()
            ->execute();
    }

    public function getFutureInitiativesByUser(string $countryCode = null)
    {
        $qb = $this->createQueryBuilder('category')
            ->select(['category', 'initiative'])
            ->leftJoin('category.initiatives', 'initiative')
            ->where('initiative.type = :initiativeType')
            ->andWhere('initiative.state > 0 AND initiative.state < 3');

        if ($countryCode) {
            $qb->andWhere(
                $qb->expr()->orX(
                    $qb->expr()->eq('category.type', ':globalType'),
                    $qb->expr()->andX(
                        $qb->expr()->eq('category.type', ':nationalType'),
                        $qb->expr()->eq('category.country', ':countryCode')
                    )
                )
            )
                ->setParameter('globalType', \App\Enum\CategoryEnum::TYPE_GLOBAL)
                ->setParameter('nationalType', \App\Enum\CategoryEnum::TYPE_NATIONAL)
                ->setParameter('countryCode', $countryCode);
        } else {
            $qb->andWhere('category.type = :globalType')
                ->setParameter('globalType', \App\Enum\CategoryEnum::TYPE_GLOBAL);
        }

        $qb->setParameter('initiativeType', InitiativeEnum::TYPE_FUTURE)
            ->addOrderBy('category.type', 'asc')
            ->addOrderBy('initiative.createdAt', 'desc');

        return $qb->getQuery()->getResult();
    }

    public function getCurrentInitiativesByUser(string $countryCode = null)
    {
        $qb = $this->createQueryBuilder('category')
            ->select(['category', 'initiative'])
            ->leftJoin('category.initiatives', 'initiative')
            ->where('initiative.type = :initiativeType')
            ->andWhere('initiative.state > 0 AND initiative.state < 3');

        if ($countryCode) {
            $qb->andWhere(
                $qb->expr()->orX(
                    $qb->expr()->eq('category.type', ':globalType'),
                    $qb->expr()->andX(
                        $qb->expr()->eq('category.type', ':nationalType'),
                        $qb->expr()->eq('category.country', ':countryCode')
                    )
                )
            )
                ->setParameter('globalType', \App\Enum\CategoryEnum::TYPE_GLOBAL)
                ->setParameter('nationalType', \App\Enum\CategoryEnum::TYPE_NATIONAL)
                ->setParameter('countryCode', $countryCode);
        } else {
            $qb->andWhere('category.type = :globalType')
                ->setParameter('globalType', \App\Enum\CategoryEnum::TYPE_GLOBAL);
        }

        $qb->setParameter('initiativeType', InitiativeEnum::TYPE_CURRENT)
            ->addOrderBy('category.type', 'asc')
            ->addOrderBy('initiative.createdAt', 'desc');

        return $qb->getQuery()->getResult();
    }

    public function getCurrentInitiatives()
    {
        return $this->createQueryBuilder('category')
            ->select(['category', 'initiative'])
            ->leftJoin('category.initiatives', 'initiative')
            ->andWhere('initiative.type = 1')
            ->andWhere('initiative.state > 0')
            ->andWhere('initiative.state < 3')
            ->addOrderBy('category.type', 'asc')
            ->addOrderBy('initiative.createdAt', 'desc')
            ->getQuery()
            ->execute();
    }

    public function getPastInitiatives()
    {
        return $this->createQueryBuilder('category')
            ->select(['category', 'initiative'])
            ->leftJoin('category.initiatives', 'initiative')
            ->andWhere('initiative.type = 2')
            ->andWhere('initiative.state = 2')
//            ->andWhere('initiative.state > 1')
//            ->andWhere('initiative.state < 4')
            ->addOrderBy('category.type', 'asc')
            ->addOrderBy('initiative.createdAt', 'desc')
            ->getQuery()
            ->execute();
    }

    public function getProgramInitiatives()
    {



        return $this->createQueryBuilder('category')

            ->select(['category', 'initiative'])
            ->leftJoin('category.initiatives', 'initiative')
            ->andWhere('initiative.type = 3')
//            ->andWhere('initiative.state > 1')
//            ->andWhere('initiative.state < 4')
            ->andWhere('initiative.state = 2')
            ->addOrderBy('category.type', 'asc')
            ->addOrderBy('initiative.createdAt', 'desc')
            ->getQuery()
            ->execute();
    }

  /**
     * All initiatives by category and type (excluding drafts)
     *
     * @return mixed
     */
    public function getInitiatives($category, $type)
    {
        $qb = $this->createQueryBuilder('category')
        ->select(['category', 'initiative'])
        ->leftJoin('category.initiatives', 'initiative')
        ->andWhere('initiative.category = :icategory')
        ->andWhere('initiative.type = :itype')
        ->addOrderBy('initiative.createdAt', 'desc');

        if ($type === InitiativeEnum::TYPE_PAST ||
            $type === InitiativeEnum::TYPE_PROGRAM
        ) {
            $qb->andWhere('initiative.state = :state')
               ->setParameter('state', InitiativeEnum::STATE_FINISHED);
        } else {
            $qb->andWhere('initiative.state = :state')
               ->setParameter('state', InitiativeEnum::STATE_ACTIVE);
        }

        $qb->setParameters([
            'icategory' => $category,
            'itype' => $type,
            'state' => ($type === InitiativeEnum::TYPE_PAST || $type === InitiativeEnum::TYPE_PROGRAM) ? InitiativeEnum::STATE_FINISHED : InitiativeEnum::STATE_ACTIVE
        ]);

        return $qb->getQuery()->execute();
    }

}
